primaryQuery:
run: inventory_items -> {
  extend: { join_one: oi is order_items on id = oi.inventory_item_id }
  where: sold_at is null or oi.status = 'Cancelled'
  aggregate: unsold is count()
}

verifyQuery:
run: inventory_items extend {
  join_one: oi is order_items on id = oi.inventory_item_id
} -> {
  where: sold_at is null or oi.status = 'Cancelled'
  group_by: product_department
  aggregate: n is count()
} -> { aggregate: unsold is n.sum() }
